                    return unsafe H.store(a, toUnchecked: &span)
                })()
            }
            var referenceLanes = sentinel
            referenceLanes.withUnsafeMutableBufferPointer { destination in
                ({
                    var span = unsafe MutableSpan(_unsafeElements: destination)
                    return H.store(a, to: &span)
                })()
            }
            mismatches.check(portLanes, referenceLanes, "a: \(describe(a))")
        }
        mismatches.record()
    }

    @Test func storeBlockUncheckedOutputSpan() {
        let mismatches = Mismatches("storeBlock unchecked output span")
        let aInputs = Inputs.vectors(H.BlockVector.self, seed: 0x02B3_D86A_E79E_7475).map(
            poisoningUpperBytes
        )
        for a in aInputs {
            let (_, portLanes) = withOutputSpan(capacity: 16 / MemoryLayout<H.Lane>.size) {
                output in
                unsafe H.append(a, toUnchecked: &output)
            }
            let (_, referenceLanes) = withOutputSpan(capacity: 16 / MemoryLayout<H.Lane>.size) {
                output in
                H.append(a, to: &output)
            }
            mismatches.check(portLanes, referenceLanes, "a: \(describe(a))")
        }
        mismatches.record()
    }
